import React, { useState, useEffect, useRef } from "react";

const HomePage: React.FC = () => {
  const [answer, setAnswer] = useState<string>(""); // Stores speech input
  const [isListening, setIsListening] = useState<boolean>(false);
  const recognitionRef = useRef<SpeechRecognition | null>(null);

  useEffect(() => {
    if ("webkitSpeechRecognition" in window || "SpeechRecognition" in window) {
      const SpeechRecognition =
        (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
      const recognition = new SpeechRecognition();

      recognition.lang = "en-US";
      recognition.interimResults = false;
      recognition.continuous = false; // Stop recognition after each speech input

      recognition.onstart = () => {
        setIsListening(true);
      };

      recognition.onend = () => {
        setIsListening(false);
      };

      recognition.onresult = (event: SpeechRecognitionEvent) => {
        const transcript = event.results[0][0].transcript;
        setAnswer((prev) => prev + " " + transcript); // Append recognized speech to input
      };

      recognition.onerror = (event) => {
        console.error("Speech recognition error:", event.error);
        setIsListening(false);
      };

      recognitionRef.current = recognition;
    } else {
      console.error("Speech Recognition API not supported in this browser.");
    }
  }, []);

  const handleMicClick = () => {
    if (!recognitionRef.current) {
      alert("Speech recognition is not supported in this browser.");
      return;
    }

    if (isListening) {
      recognitionRef.current.stop();
    } else {
      setAnswer(""); // Clear previous text before starting
      recognitionRef.current.start();
    }
  };

  return (
    <div>
      <h2>Speak Your Answer</h2>
      <input
        type="text"
        value={answer}
        onChange={(e) => setAnswer(e.target.value)}
        placeholder="Your answer will appear here..."
      />
      <button
        className={`mic-button ${isListening ? "active" : ""}`}
        title={isListening ? "Click to stop recording" : "Click to start recording"}
        onClick={handleMicClick}
      >
        🎤
      </button>
    </div>
  );
};

export default HomePage;
